import argparse
import sys
from .hook import cmd_edit
from .hook import cmd_prompt
from .hook import cmd_start
from .hook import cmd_stop
from . import cmd_install
from . import cmd_uninstall
from . import cmd_model
from . import cmd_codex_install
from . import cmd_codex_uninstall
from .update_checker import fetch_latest_version, maybe_notify_update
from .version import __version__


# Windows 使用 msvcrt，Unix 使用 tty/termios
if sys.platform == 'win32':
    import msvcrt
    def _getch():
        ch = msvcrt.getch()
        if ch in (b'\x00', b'\xe0'):
            ch = msvcrt.getch()
            return '\x1b[B'
        elif ch == b'\r':
            return '\n'
        return ch.decode('utf-8', errors='ignore')
else:
    import tty
    import termios
    def _getch():
        fd = sys.stdin.fileno()
        old_settings = termios.tcgetattr(fd)
        try:
            tty.setraw(fd)
            ch = sys.stdin.read(1)
            if ch == '\x1b':
                ch += sys.stdin.read(2)
        finally:
            termios.tcsetattr(fd, termios.TCSADRAIN, old_settings)
        return ch


def _select_tool() -> str:
    """交互式选择安装目标工具，返回 'claude' 或 'codex'"""
    tools = [
        ("claude", "Claude Code"),
        ("codex",  "Codex"),
    ]
    current = 0

    def draw():
        rows = len(tools) + 3
        print(f"\033[{rows}A", end="")
        print("\033[J", end="")
        print("请选择要配置的工具 (↑↓ 切换, Enter 确认):\n")
        for i, (_, name) in enumerate(tools):
            prefix = "> [●]" if i == current else "  [ ]"
            print(f"{prefix} {name}")
        print()

    # 初次打印（先占行）
    print("\n" * (len(tools) + 3))
    draw()

    while True:
        key = _getch()
        if key == '\x1b[A':
            current = (current - 1) % len(tools)
            draw()
        elif key == '\x1b[B':
            current = (current + 1) % len(tools)
            draw()
        elif key in ('\r', '\n'):
            break

    selected_id, selected_name = tools[current]
    print(f"\033[32m已选择: {selected_name}\033[0m\n")
    return selected_id


def _set_reporter_ide_type(ide_type: int):
    try:
        from ahclaude_plugin.ahreporter import AHReporter
        AHReporter.get_instance().set_ide_type(ide_type)
    except Exception:
        pass


def _should_notify_update(main_command, sub_command) -> bool:
    if main_command is None:
        return True
    if main_command == 'claude':
        return sub_command in (None, 'install', 'model')
    if main_command == 'codex':
        return sub_command in (None, 'install', 'model')
    return False


def _check_update_command():
    current_version = __version__
    print(f"当前版本: {current_version}")
    try:
        latest_version = fetch_latest_version()
    except Exception as e:
        print(f"检查更新失败: {e}")
        return 1

    if not latest_version:
        print("未能从更新源解析出最新版本")
        return 1

    print(f"最新版本: {latest_version}")
    if latest_version == current_version:
        print("当前已是最新版本")
    else:
        print("检测到可用更新")
    return 0


def main():
    parser = argparse.ArgumentParser(description="Auto++ 插件配置工具")

    subparsers = parser.add_subparsers(dest="main_command", help="子命令集合")

    # ── claude 子命令 ──────────────────────────────────────────────
    parser_claude = subparsers.add_parser('claude', help="Claude Code 相关命令")
    claude_subparsers = parser_claude.add_subparsers(dest="claude_command", help="Claude 子命令")

    parser_edit = claude_subparsers.add_parser('edit', help="编辑 hook（PostToolUse）")
    parser_edit.add_argument('--test', action='store_true')

    parser_prompt = claude_subparsers.add_parser('prompt', help="提问 hook（UserPromptSubmit）")
    parser_prompt.add_argument('--test', action='store_true')

    parser_start = claude_subparsers.add_parser('start', help="记录启动信息")
    parser_start.add_argument("session_id", nargs="?", help="Session ID")
    parser_start.add_argument("working_directory", nargs="?", help="工作目录")
    parser_start.add_argument('--test', action='store_true')

    claude_activate = claude_subparsers.add_parser('activate', help="发送请求前激活 token（PreToolUse）")
    claude_activate.add_argument('--test', action='store_true')

    claude_subparsers.add_parser('install', help="安装 hook 配置")
    claude_subparsers.add_parser('uninstall', help="卸载 hook 配置")
    claude_subparsers.add_parser('model', help="切换模型")

    subparsers.add_parser('version', help="显示 auto++ 当前版本")
    subparsers.add_parser('check-update', help="检查是否有新版本")

    # ── codex 子命令 ───────────────────────────────────────────────
    parser_codex = subparsers.add_parser('codex', help="Codex 相关命令")
    codex_subparsers = parser_codex.add_subparsers(dest="codex_command", help="Codex 子命令")

    codex_edit = codex_subparsers.add_parser('edit', help="编辑 hook（PostToolUse）")
    codex_edit.add_argument('--test', action='store_true')

    codex_prompt = codex_subparsers.add_parser('prompt', help="提问 hook（UserPromptSubmit）")
    codex_prompt.add_argument('--test', action='store_true')

    codex_start = codex_subparsers.add_parser('start', help="记录启动信息")
    codex_start.add_argument("session_id", nargs="?")
    codex_start.add_argument("working_directory", nargs="?")
    codex_start.add_argument('--test', action='store_true')

    codex_stop = codex_subparsers.add_parser('stop', help="回合结束 hook")
    codex_stop.add_argument('--test', action='store_true')

    codex_activate = codex_subparsers.add_parser('activate', help="发送请求前激活 token（PreToolUse）")
    codex_activate.add_argument('--test', action='store_true')

    codex_subparsers.add_parser('install', help="安装 Codex 配置")
    codex_subparsers.add_parser('uninstall', help="卸载 Codex 配置")
    codex_subparsers.add_parser('model', help="切换模型")

    # ──────────────────────────────────────────────────────────────
    args = parser.parse_args()

    if args.main_command == 'version':
        print(__version__)
        return

    if args.main_command == 'check-update':
        raise SystemExit(_check_update_command())

    sub_command = None
    if args.main_command == 'claude':
        sub_command = args.claude_command
    elif args.main_command == 'codex':
        sub_command = args.codex_command

    if _should_notify_update(args.main_command, sub_command):
        update_message = maybe_notify_update()
        if update_message:
            print(update_message)
            print()

    # 无参数：弹出工具选择菜单
    if args.main_command is None:
        try:
            from . import cmd_login
            if not cmd_login.is_logged_in():
                print("未检测到登录态，正在启动登录流程...")
                cmd_login.ensure_login()
                print()
        except Exception:
            pass
        tool = _select_tool()
        if tool == 'claude':
            cmd_install.install()
        else:
            cmd_codex_install.install()
        return

    # ── claude 路由 ────────────────────────────────────────────────
    if args.main_command == 'claude':
        _set_reporter_ide_type(300)
        if args.claude_command is None:
            cmd_install.install()
            return

        if args.claude_command == 'edit':
            if getattr(args, 'test', False):
                cmd_edit.test_main()
            else:
                cmd_edit.handle_edit()
        elif args.claude_command == 'prompt':
            if getattr(args, 'test', False):
                cmd_prompt.test_main()
            else:
                cmd_prompt.handle_prompt(emit_output=False)
        elif args.claude_command == 'start':
            if getattr(args, 'test', False):
                cmd_start.test_main()
            else:
                cmd_start.handle_start(args.session_id, args.working_directory)
        elif args.claude_command == 'activate':
            cmd_prompt.handle_activate()
        elif args.claude_command == 'install':
            cmd_install.install()
        elif args.claude_command == 'uninstall':
            cmd_uninstall.uninstall()
        elif args.claude_command == 'model':
            cmd_model.run_model_selector(product="claude")
        else:
            parser_claude.print_help()

    # ── codex 路由 ─────────────────────────────────────────────────
    elif args.main_command == 'codex':
        _set_reporter_ide_type(400)
        if args.codex_command is None:
            cmd_codex_install.install()
            return

        if args.codex_command == 'edit':
            if getattr(args, 'test', False):
                cmd_edit.test_main()
            else:
                cmd_edit.handle_edit()
        elif args.codex_command == 'prompt':
            if getattr(args, 'test', False):
                cmd_prompt.test_main()
            else:
                cmd_prompt.handle_prompt(emit_output=False)
        elif args.codex_command == 'start':
            if getattr(args, 'test', False):
                cmd_start.test_main()
            else:
                cmd_start.handle_start(args.session_id, args.working_directory, emit_output=False)
        elif args.codex_command == 'stop':
            if getattr(args, 'test', False):
                parser_codex.print_help()
            else:
                cmd_stop.handle_stop()
        elif args.codex_command == 'activate':
            cmd_prompt.handle_activate()
        elif args.codex_command == 'install':
            cmd_codex_install.install()
        elif args.codex_command == 'uninstall':
            cmd_codex_uninstall.uninstall()
        elif args.codex_command == 'model':
            from . import cmd_codex_uninstall
            cmd_model.run_model_selector(
                login_command="auto++ claude login",
                reset_label="还原 Codex 默认配置",
                restart_message="请重启 Codex 以加载新模型",
                reset_uninstall_fn=cmd_codex_uninstall.uninstall,
                update_claude_settings=False,
                after_select_fn=cmd_codex_install.refresh_codex_config_after_model_select,
                product="codex",
            )
        else:
            parser_codex.print_help()

    else:
        parser.print_help()


if __name__ == '__main__':
    main()
